import type { EngineInterface, Register, Timer } from 'claude-code';

import type { PrSnapshot } from '../types';
import {
  byState,
  ciText,
  isRunning,
  fetchSnapshot,
  isConflicted,
  landPrompt,
  statusText,
  summary,
} from './pr';

const PANE = 'pr-steward';
const TITLE = 'Pull request';
const snapshotRef = { plugin: 'pr-steward', key: 'snapshot' } as const;
const POLL_MS = 60_000;
/** CI needs a moment to register a push's checks */
const AFTER_PUSH_MS = 15_000;

let latest: Promise<PrSnapshot> | undefined;
/** Whether the branch last had a PR; a failed read only shows then, not in repos gh can't read at all */
let hadPr = false;

/**
 * Reads the PR through gh; reads run one after another, so each caller sees
 * GitHub as of its call. Never rejects, so callers can fire and forget.
 */
function refresh($: EngineInterface): Promise<PrSnapshot> {
  const after = latest;
  latest = (async () => {
    await after;
    const previous = (await $.state.get(snapshotRef)).value ?? null;
    const next = await fetchSnapshot(
      argv => $.process.run(argv),
      path => $.fs.read(path),
    );
    await $.state.set(snapshotRef, next);
    // a failed read says nothing about the PR, so it keeps the last answer
    if (next.kind === 'pr') hadPr = true;
    else if (next.kind === 'none') hadPr = false;
    $.ui.status(hadPr ? statusText(next) : undefined);
    announce($, previous, next);
    return next;
  })().catch((error): PrSnapshot => ({
    kind: 'error',
    message: String(error),
  }));
  return latest;
}

async function markReady($: EngineInterface) {
  const ran = await $.process.run(['gh', 'pr', 'ready']);
  if (ran.exitCode !== 0)
    $.ui.toast(`gh pr ready failed: ${ran.stderr.trim()}`);
  await refresh($);
}

/** Asks the model to land the PR; without one, says why not */
async function land($: EngineInterface): Promise<string> {
  const snapshot = await refresh($);
  if (snapshot.kind !== 'pr') return summary(snapshot);
  await $.prompt.submit({ text: landPrompt(snapshot) });
  return 'Landing this branch’s pull request.';
}

let afterPush: Timer | undefined;
let branch: string | undefined;

let branchQueue: Promise<void> | undefined;

/**
 * Refreshes at once when Claude switched branches, so the pane never shows the
 * old branch's PR. Any command can switch (aliases, scripts), so this runs a
 * local git read after each one; reads run in order so a stale one can't win.
 */
function checkBranch($: EngineInterface) {
  const after = branchQueue;
  branchQueue = (async () => {
    await after;
    const ran = await $.process.run([
      'git',
      'rev-parse',
      '--abbrev-ref',
      'HEAD',
    ]);
    if (ran.exitCode !== 0) return;
    const now = ran.stdout.trim();
    const switched = branch !== undefined && now !== branch;
    branch = now;
    if (switched) hadPr = false;
    // not awaited: the next branch read shouldn't wait on GitHub
    if (switched) void refresh($);
  })().catch(() => undefined);
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await Promise.all([
      $.command.register({
        name: 'pr',
        description:
          "Show this branch's pull request: CI, review threads, preview",
      }),
      $.command.register({
        name: 'land',
        description: "Drive this branch's pull request to mergeable",
      }),
      $.tool.register({
        name: 'pr_status',
        description:
          "Current state of this branch's pull request, read fresh from GitHub: merge state, failing and running checks with links, unresolved review threads with their first line and link, and the preview link when the repo configures one. Use it instead of re-querying GitHub when checking whether a PR is ready.",
        isDeferred: false,
      }),
    ]);
    $.clock.every(POLL_MS, () => void refresh($));
    void refresh($);
    void checkBranch($);
    return next(e);
  });

  on('command.run', { command: 'pr' }, async $ => {
    await $.ui.open({ id: PANE, title: TITLE });
    void refresh($);
    return { text: 'Opened the pull request pane.' };
  });

  on('command.run', { command: 'land' }, async $ => {
    return { text: await land($) };
  });

  on('tool.call', { tool: 'mcp__pr-steward__pr_status' }, async $ => ({
    result: summary(await refresh($)),
  }));

  // A failure here must not block Bash; .catch's next(e) replays the settled call, never running it twice
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e);
    void checkBranch($);
    const git = ran.isError ? undefined : ran.result?.gitOperation;
    if (git?.push || git?.pr) {
      afterPush?.cancel();
      afterPush = $.clock.after(AFTER_PUSH_MS, () => void refresh($));
    }
    return ran;
  }).catch(($, e, next) => next(e));

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button, Link } = $.ui.resolve(e);
    const snapshot = (await $.state.get(snapshotRef)).value ?? null;
    const actions = (
      <Box key="actions" gap={1}>
        <Button
          key="refresh"
          label="Refresh"
          hotkey="r"
          onPress={() => refresh($)}
        />
        {snapshot?.kind === 'pr' && (
          <Button
            key="land"
            label="Land"
            variant="primary"
            hotkey="l"
            onPress={() => land($)}
          />
        )}
        {snapshot?.kind === 'pr' && snapshot.pr.isDraft && (
          <Button key="ready" label="Mark ready" onPress={() => markReady($)} />
        )}
      </Box>
    );

    if (snapshot?.kind !== 'pr')
      return (
        <Box flexDirection="column">
          <Text dimColor>
            {snapshot === null ?
              'Reading the pull request…'
            : summary(snapshot)}
          </Text>
          {actions}
        </Box>
      );

    const { pr } = snapshot;
    const failing = byState(pr, 'fail');
    const pending = byState(pr, 'pending');
    const passing = byState(pr, 'pass');
    return (
      <Box flexDirection="column" gap={1}>
        <Box flexDirection="column">
          <Link href={pr.url}>
            #{pr.number} {pr.title}
          </Link>
          <Text dimColor>
            {pr.isDraft ? 'Draft' : 'Ready for review'} ·{' '}
            {pr.mergeState.toLowerCase()}
            {pr.reviewDecision ?
              ` · ${pr.reviewDecision.toLowerCase().replace('_', ' ')}`
            : ''}
          </Text>
          {isConflicted(pr) && (
            <Text color="error">Conflicts with its base branch</Text>
          )}
          {pr.preview && <Link href={pr.preview}>Website preview</Link>}
        </Box>

        <Box flexDirection="column">
          <Text bold>
            Checks{' '}
            <Text dimColor>
              {failing.length} failing · {pending.length} running ·{' '}
              {passing.length} passing
            </Text>
          </Text>
          {failing.map((check, i) =>
            check.url ?
              <Link key={`fail-${i}`} href={check.url}>
                ✗ {check.name}
              </Link>
            : <Text key={`fail-${i}`} color="error">
                ✗ {check.name}
              </Text>,
          )}
          {pending.map((check, i) => (
            <Text key={`run-${i}`} color="warning">
              ○ {check.name}
            </Text>
          ))}
          {failing.length + pending.length === 0 &&
            (pr.ci === 'pass' ?
              <Text color="success">✓ All checks pass</Text>
            : <Text dimColor>{ciText(pr)}</Text>)}
        </Box>

        <Box flexDirection="column">
          <Text bold>
            Open threads <Text dimColor>{pr.threads.length}</Text>
          </Text>
          {pr.threads.map((thread, i) => (
            <Link key={`thread-${i}`} href={thread.url}>
              {thread.author}: {thread.body}
            </Link>
          ))}
        </Box>

        {actions}
      </Box>
    );
  });
};

/** Each commit's CI as last seen, so each run's result is announced once */
const runs = new Map<string, 'running' | 'settled'>();

/** A toast when CI settles or the PR starts conflicting, so nobody has to poll */
function announce(
  $: EngineInterface,
  previous: PrSnapshot | null,
  next: PrSnapshot,
) {
  if (next.kind !== 'pr') return;
  const { pr } = next;
  // a commit first seen settled stays quiet; a re-run is announced again, but
  // an empty read of a commit already seen is only GitHub catching up
  const seen = runs.get(pr.head);
  if (isRunning(pr) || (pr.ci === 'none' && !seen))
    runs.set(pr.head, 'running');
  else if (pr.ci !== 'none') {
    runs.set(pr.head, 'settled');
    const failing = byState(pr, 'fail');
    if (seen === 'running')
      $.ui.toast(
        failing.length ?
          `PR #${pr.number}: ${failing.length} failing (${failing.map(c => c.name).join(', ')})`
        : `PR #${pr.number}: ${ciText(pr)}`,
      );
  }
  if (
    previous?.kind === 'pr' &&
    previous.pr.number === pr.number &&
    !isConflicted(previous.pr) &&
    isConflicted(pr)
  )
    $.ui.toast(`PR #${pr.number} now conflicts with its base branch`);
}

